import React, { useState, useEffect, useRef } from 'react';
import { Container, Button, Input, InputGroup, InputGroupText } from 'reactstrap';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';

const ChatRoom = ({ chatId, otherUserId, loginUserId, goBack }) => {
    const [message, setMessage] = useState('');
    const [messages, setMessages] = useState([]);
    const [proposals, setProposals] = useState([]); // 새로운 상태 변수 추가
    const stompClient = useRef(null);
    const messagesEndRef = useRef(null);

    useEffect(() => {
        fetchMessages(chatId);
        fetchProposals(chatId); // 제안서 데이터 가져오기
        connectWebSocket();

        return () => {
            if (stompClient.current) {
                stompClient.current.deactivate();
            }
        };
    }, [chatId]);

    useEffect(() => {
        scrollToBottom();
    }, [messages, proposals]); // 제안서 데이터 변경 시 스크롤 내리기

    const fetchMessages = (headerId) => {
        fetch(`http://localhost:8080/api/messages/byHeaderId/${headerId}`)
            .then((response) => response.json())
            .then((data) => {
                console.log('Fetched messages:', data); // 로그 추가
                if (Array.isArray(data)) {
                    setMessages(data);
                } else {
                    setMessages([]);
                }
            })
            .catch((error) => console.error('Error:', error));
    };

    const fetchProposals = (headerId) => {
        fetch(`http://localhost:8080/api/sendProposal/byHeaderId/${headerId}`)
            .then((response) => response.json())
            .then((data) => {
                console.log('Fetched proposals:', data); // 로그 추가
                if (Array.isArray(data)) {
                    setProposals(data);
                } else {
                    setProposals([]);
                }
            })
            .catch((error) => console.error('Error:', error));
    };

    const connectWebSocket = () => {
        const socket = new SockJS('http://localhost:8080/ws');
        stompClient.current = new Client({
            webSocketFactory: () => socket,
            onConnect: () => {
                console.log('Connected to WebSocket'); // 로그 추가
                stompClient.current.subscribe(`/topic/chat/${chatId}`, (message) => {
                    const receivedMessage = JSON.parse(message.body);
                    console.log('Received message:', receivedMessage); // 로그 추가
                    setMessages((prevMessages) => [...prevMessages, receivedMessage]);
                });
            },
            onStompError: (frame) => {
                console.error('Broker reported error: ' + frame.headers['message']);
                console.error('Additional details: ' + frame.body);
            },
        });

        stompClient.current.activate();
    };

    const formatDate = (date) => {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        const seconds = String(date.getSeconds()).padStart(2, '0');
        return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
    };

    const handleSend = () => {
        if (message.trim() !== '') {
            const newMessage = {
                headerId: chatId,
                fromId: loginUserId,
                toId: otherUserId,
                content: message.trim(),
                time: formatDate(new Date()), // 현재 시간을 설정합니다.
            };
            setMessage('');

            // Save message to the server
            fetch('http://localhost:8080/api/messages', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(newMessage),
            })
                .then((response) => response.json())
                .then((data) => {
                    console.log('Message sent:', data); // 로그 추가
                    // WebSocket을 통해 새 메시지를 브로드캐스트합니다.
                    stompClient.current.publish({
                        destination: `/app/chat/${chatId}`,
                        body: JSON.stringify(data),
                    });
                })
                .catch((error) => console.error('Error:', error));
        }
    };

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    const renderMessage = (msg) => (
        <div
            key={msg.id}
            style={{
                display: 'flex',
                justifyContent: msg.fromId === loginUserId ? 'flex-end' : 'flex-start',
                marginBottom: '10px',
            }}
        >
            <div
                style={{
                    maxWidth: '60%',
                    padding: '10px',
                    borderRadius: '10px',
                    background: msg.fromId === loginUserId ? '#007bff' : '#f1f0f0',
                    color: msg.fromId === loginUserId ? '#fff' : '#000',
                    wordWrap: 'break-word',
                }}
            >
                {msg.content}
            </div>
        </div>
    );

    const renderProposal = (proposal) => (
        <div
            key={proposal.id}
            style={{
                display: 'flex',
                justifyContent: proposal.fromId === loginUserId ? 'flex-end' : 'flex-start',
                marginBottom: '10px',
            }}
        >
            <div
                style={{
                    maxWidth: '60%',
                    padding: '10px',
                    borderRadius: '10px',
                    background: proposal.fromId === loginUserId ? '#28a745' : '#e9ecef',
                    wordWrap: 'break-word',
                }}
            >
                <div>
                    <strong>제안서: {proposal.goodName}</strong>
                </div>
                <div>
                    <img
                        src={`http://localhost:8080/uploads/${proposal.photoUrl}`}
                        alt={proposal.goodName}
                        style={{ maxWidth: '100%', height: 'auto', marginBottom: '5px' }}
                    />
                </div>
                <div>
                    <p>{proposal.goodDetail}</p>
                    <p>{proposal.goodRequire}</p>
                    <p>업로드 기간: {proposal.term}</p>
                    <p>지급 방법: {proposal.payWay}</p>
                    <p>총 금액: {proposal.pay}원</p>
                </div>
            </div>
        </div>
    );

    return (
        <Container style={{ position: 'relative', height: '100vh', padding: '0' }}>
            <div>
                <Button style={{ fontSize: '10px', margin: '10px' }} color="secondary" onClick={goBack}>
                    ◁
                </Button>
                {chatId}-{otherUserId}
            </div>
            <div
                style={{
                    position: 'absolute',
                    top: '6%',
                    left: '0',
                    right: '0',
                    bottom: '50%',
                    overflowY: 'scroll',
                    padding: '5px',
                }}
            >
                {messages.map((msg) => renderMessage(msg))}
                {proposals.map((proposal) => renderProposal(proposal))}
                <div ref={messagesEndRef} />
            </div>
            <div
                style={{
                    position: 'absolute',
                    top: '50%',
                    left: '0',
                    width: '100%',
                    padding: '10px',
                    backgroundColor: '#fff',
                    borderTop: '1px solid #ccc',
                }}
            >
                <InputGroup>
                    <Input
                        type="text"
                        value={message}
                        onChange={(e) => setMessage(e.target.value)}
                        placeholder="메시지를 입력하세요"
                    />
                    <InputGroupText>
                        <Button color="primary" onClick={handleSend}>
                            전송
                        </Button>
                    </InputGroupText>
                </InputGroup>
            </div>
        </Container>
    );
};

export default ChatRoom;
